// js/data/managerial-terms.js
// Key terms from all 24 chapters of Horngren Cost Accounting 17th Edition

export const TERMS = [
  { chapter: 1, term: "Management Accounting", definition: "Measures, analyzes, and reports financial and nonfinancial information that helps managers make decisions to fulfill the goals of an organization. Focuses on internal reporting." },
  { chapter: 1, term: "Financial Accounting", definition: "Measures and records business transactions and provides financial statements based on GAAP. Focuses on reporting to external parties such as investors and banks." },
  { chapter: 1, term: "Cost Accounting", definition: "Measures, analyzes, and reports financial and nonfinancial information relating to the costs of acquiring or using resources. Provides information for both management and financial accounting." },
  { chapter: 1, term: "Value Chain", definition: "The sequence of business functions by which a product is made progressively more useful to customers: R&D, design, production, marketing, distribution, and customer service." },
  { chapter: 1, term: "Supply Chain", definition: "The flow of goods, services, and information from the initial sources of materials and services to the delivery of products to consumers, regardless of whether those activities occur in the same organization or in other organizations." },
  { chapter: 1, term: "Strategy", definition: "Specifies how an organization matches its own capabilities with the opportunities in the marketplace to accomplish its objectives." },
  { chapter: 1, term: "Cost Leadership", definition: "An organization's ability to achieve lower costs relative to competitors through productivity and efficiency improvements, elimination of waste, and tight cost control." },
  { chapter: 1, term: "Product Differentiation", definition: "An organization's ability to offer products or services perceived by its customers to be superior and unique relative to the products or services of its competitors." },
  { chapter: 1, term: "Planning", definition: "Selecting organization goals, predicting results under various alternative ways of achieving those goals, deciding how to attain the desired goals, and communicating the goals and how to achieve them to the entire organization." },
  { chapter: 1, term: "Control", definition: "Taking actions that implement the planning decisions, evaluating past performance, and providing feedback and learning that will help future decision making." },
  { chapter: 1, term: "Controller", definition: "The financial executive primarily responsible for management accounting and financial accounting. Also referred to as chief accounting officer." },
  { chapter: 1, term: "Chief Financial Officer (CFO)", definition: "Executive responsible for overseeing the financial operations of an organization. Also called finance director." },
  { chapter: 1, term: "Line Management", definition: "Managers (for example, in production, marketing, or distribution) who are directly responsible for attaining the goals of the organization." },
  { chapter: 1, term: "Staff Management", definition: "Staff (such as management accountants and human resources managers) who provide advice, support, and assistance to line management." },
  { chapter: 2, term: "Cost Object", definition: "Anything for which a separate measurement of costs is desired. Examples: a product, service, project, customer, activity, or department." },
  { chapter: 2, term: "Direct Cost", definition: "A cost that is related to a particular cost object and can be traced to it in an economically feasible way. Also called cost tracing." },
  { chapter: 2, term: "Indirect Cost", definition: "A cost that is related to a particular cost object but cannot be traced to it in an economically feasible way. Indirect costs are allocated to cost objects." },
  { chapter: 2, term: "Cost Allocation", definition: "The process of assigning indirect costs to a particular cost object using a reasonable allocation base." },
  { chapter: 2, term: "Cost Tracing", definition: "The assignment of direct costs to a particular cost object using a direct measure of the resources consumed." },
  { chapter: 2, term: "Variable Cost", definition: "A cost that changes in total in proportion to changes in the volume or activity level of a cost object. The cost per unit remains constant." },
  { chapter: 2, term: "Fixed Cost", definition: "A cost that remains unchanged in total for a given time period despite wide changes in the volume or activity level of a cost object. The cost per unit decreases as volume increases." },
  { chapter: 2, term: "Cost Driver", definition: "A variable that causally affects total costs over a given time span, such as units produced, machine hours, or miles driven." },
  { chapter: 2, term: "Relevant Range", definition: "The band of activity within which a specific relationship between cost and volume is valid. Outside this range, cost behavior may change." },
  { chapter: 2, term: "Inventoriable Costs", definition: "All costs of a product that are considered assets when incurred and expensed as cost of goods sold only when the product is sold. For manufacturers, these are all manufacturing costs." },
  { chapter: 2, term: "Period Costs", definition: "All costs in the income statement other than cost of goods sold. Expensed in the period incurred. Examples: R&D, marketing, distribution, customer service." },
  { chapter: 2, term: "Direct Materials Costs", definition: "Acquisition costs of all materials that eventually become part of the cost object and can be traced to it in an economically feasible way." },
  { chapter: 2, term: "Direct Manufacturing Labor Costs", definition: "Compensation of all manufacturing labor that can be traced to the cost object in an economically feasible way." },
  { chapter: 2, term: "Manufacturing Overhead Costs", definition: "All manufacturing costs that are related to the cost object but cannot be traced to it. Also called indirect manufacturing costs or factory overhead." },
  { chapter: 2, term: "Prime Costs", definition: "All direct manufacturing costs: direct materials + direct manufacturing labor." },
  { chapter: 2, term: "Conversion Costs", definition: "All manufacturing costs other than direct materials: direct manufacturing labor + manufacturing overhead." },
  { chapter: 2, term: "Cost of Goods Manufactured", definition: "The cost of goods brought to completion during the period. Calculated as: Beginning WIP + Total Manufacturing Costs Incurred minus Ending WIP." },
  { chapter: 2, term: "Unit Cost", definition: "Also called average cost. Total cost divided by the number of units. Must be interpreted cautiously because fixed costs per unit change with volume." },
  { chapter: 2, term: "Product Cost", definition: "The sum of costs assigned to a product for a specific purpose. Differs depending on whether the purpose is financial reporting, pricing decisions, or government contracts." },
  { chapter: 2, term: "Work-in-Process Inventory", definition: "Goods partially worked on but not yet completed. Appears as an asset on the balance sheet." },
  { chapter: 3, term: "Cost-Volume-Profit (CVP) Analysis", definition: "A tool managers use to study the behavior of and relationship among total revenues, total costs, and operating income as changes occur in units sold, selling price, variable cost per unit, or fixed costs." },
  { chapter: 3, term: "Contribution Margin", definition: "The difference between total revenues and total variable costs. Contribution margin = Total revenues - Total variable costs." },
  { chapter: 3, term: "Contribution Margin per Unit", definition: "Selling price minus variable cost per unit. Represents how much each unit sold contributes toward covering fixed costs and then generating profit." },
  { chapter: 3, term: "Contribution Margin Percentage", definition: "Also called contribution margin ratio. Contribution margin divided by revenues. Represents the contribution margin per dollar of revenue." },
  { chapter: 3, term: "Contribution Income Statement", definition: "An income statement that groups costs into variable costs and fixed costs to highlight contribution margin. Format: Revenue - Variable Costs = CM - Fixed Costs = Operating Income." },
  { chapter: 3, term: "Breakeven Point (BEP)", definition: "The quantity of output sold at which total revenues equal total costs — the quantity that results in $0 operating income. BEP (units) = Fixed Costs / Contribution Margin per Unit." },
  { chapter: 3, term: "Target Operating Income", definition: "The desired level of operating income used to determine the required sales volume. Units required = (Fixed Costs + Target Operating Income) / CM per Unit." },
  { chapter: 3, term: "Net Income", definition: "Operating income minus income taxes. When income taxes are present, convert target net income to target operating income: Target OI = Target Net Income / (1 - Tax Rate)." },
  { chapter: 3, term: "Sensitivity Analysis", definition: "A \"what if\" technique that examines how an outcome changes if original predicted data are not achieved or if an underlying assumption changes." },
  { chapter: 3, term: "Margin of Safety", definition: "Budgeted (or actual) revenues minus breakeven revenues. Indicates how far revenues can fall before a loss occurs. Often expressed as a percentage of budgeted revenues." },
  { chapter: 3, term: "Operating Leverage", definition: "The effect that fixed costs have on changes in operating income as changes occur in units sold. Degree of operating leverage = Contribution Margin / Operating Income." },
  { chapter: 3, term: "Sales Mix", definition: "The quantities or proportions of various products that constitute a company's total unit sales. Breakeven in a multi-product company depends on the assumed sales mix." },
  { chapter: 3, term: "Revenue Driver", definition: "A variable, such as number of units sold, that causally affects revenues. Analogous to a cost driver for costs." },
  { chapter: 3, term: "PV Graph", definition: "Profit-volume graph. Shows how changes in the quantity of units sold affect operating income directly. The PV line starts at -Fixed Costs at zero units and crosses zero at the breakeven point." },
  { chapter: 3, term: "Gross Margin vs. Contribution Margin", definition: "Gross margin = Revenues - Cost of Goods Sold (includes fixed manufacturing costs). Contribution margin = Revenues - All Variable Costs. They differ by fixed manufacturing costs and variable non-manufacturing costs." },
  { chapter: 4, term: "Job-Costing System", definition: "A costing system in which the cost object is a unit or multiple units of a distinct product or service called a job. Each job generally uses different amounts of resources." },
  { chapter: 4, term: "Process-Costing System", definition: "A costing system in which the cost object is masses of identical or similar units of a product or service. Costs are averaged over all units produced." },
  { chapter: 4, term: "Job", definition: "A unit or multiple units of a distinct product or service — the cost object in a job-costing system. Examples: a specific construction project, an audit engagement, a custom machine." },
  { chapter: 4, term: "Job-Cost Record", definition: "Also called a job-cost sheet. A document used to record and accumulate all costs assigned to a specific job, starting when work begins. Contains direct materials, direct labor, and overhead sections." },
  { chapter: 4, term: "Source Document", definition: "An original record that supports journal entries in an accounting system. Examples: materials-requisition record, labor-time sheet, purchase invoice." },
  { chapter: 4, term: "Materials-Requisition Record", definition: "A source document that contains information about the cost of direct materials used on a specific job and in a specific department." },
  { chapter: 4, term: "Labor-Time Sheet", definition: "A source document that contains information about the amount of labor time used for a specific job in a specific department. Used to trace direct labor costs to jobs." },
  { chapter: 4, term: "Normal Costing", definition: "A costing system that traces direct costs using actual rates times actual quantities, and allocates indirect costs using budgeted rates times actual quantities of cost-allocation bases." },
  { chapter: 4, term: "Actual Costing", definition: "A costing system that traces direct costs using actual rates times actual quantities, and allocates indirect costs using actual rates times actual quantities of cost-allocation bases. Actual rates are only known at year-end." },
  { chapter: 4, term: "Budgeted Indirect-Cost Rate", definition: "Calculated at the start of the fiscal year as: Budgeted annual indirect costs / Budgeted annual quantity of the cost-allocation base. Used in normal costing to allocate overhead to jobs throughout the year." },
  { chapter: 4, term: "Cost Pool", definition: "A grouping of individual indirect cost items. Cost items in a pool have the same cost-allocation base and are allocated together to cost objects." },
  { chapter: 4, term: "Cost-Allocation Base", definition: "A systematic way to link an indirect cost or group of indirect costs to cost objects. The ideal base is the cost driver of the indirect costs. Can be financial (direct labor cost) or nonfinancial (machine-hours)." },
  { chapter: 4, term: "Manufacturing Overhead Allocated", definition: "Also called manufacturing overhead applied. The amount of manufacturing overhead allocated to individual jobs based on the budgeted rate multiplied by the actual quantity of the allocation base used." },
  { chapter: 4, term: "Underallocated Indirect Costs", definition: "Occurs when allocated indirect costs are less than actual indirect costs incurred. Also called underapplied or underabsorbed overhead. Formula: Actual OH - Allocated OH > 0." },
  { chapter: 4, term: "Overallocated Indirect Costs", definition: "Occurs when allocated indirect costs are greater than actual indirect costs incurred. Also called overapplied or overabsorbed overhead. Formula: Actual OH - Allocated OH < 0." },
  { chapter: 4, term: "Proration", definition: "An approach to disposing of under- or overallocated overhead that spreads the difference among ending WIP, Finished Goods, and Cost of Goods Sold in proportion to the overhead allocated in each account." },
  { chapter: 4, term: "Adjusted Allocation-Rate Approach", definition: "Restates all overhead entries using actual overhead cost rates rather than budgeted rates. Adjusts both general ledger and subsidiary ledger job-cost records. Most accurate method." },
  { chapter: 4, term: "Write-Off to Cost of Goods Sold", definition: "The simplest disposal method — the entire under- or overallocated overhead is added to (or subtracted from) Cost of Goods Sold. Appropriate when the amount is immaterial." },
  { chapter: 5, term: "Activity-Based Costing (ABC)", definition: "A costing system that refines a costing system by identifying individual activities as the fundamental source of indirect costs. ABC systems calculate costs of individual activities and assign costs to cost objects based on the mix of activities needed to produce each product or service." },
  { chapter: 5, term: "Activity", definition: "An event, task, or unit of work with a specified purpose. Examples: designing products, setting up machines, operating machines, distributing products. More informally, activities are verbs -- things a firm does." },
  { chapter: 5, term: "Cost Hierarchy", definition: "A categorization of activity-cost pools based on different types of cost drivers or different degrees of difficulty in determining cause-and-effect relationships. The four levels are: output unit-level, batch-level, product-sustaining, and facility-sustaining." },
  { chapter: 5, term: "Output Unit-Level Costs", definition: "Costs of activities performed that vary with each individual unit of the cost object. Example: machine energy costs that increase with each unit produced." },
  { chapter: 5, term: "Batch-Level Costs", definition: "Costs of activities that vary with a group of units rather than each individual unit. Example: setup costs that vary with the number of setups (batches), regardless of batch size." },
  { chapter: 5, term: "Product-Sustaining Costs", definition: "Costs of activities undertaken to support individual products or services regardless of the number of units or batches produced. Example: design costs that depend on product complexity, not production volume." },
  { chapter: 5, term: "Facility-Sustaining Costs", definition: "Costs of activities that support the organization as a whole and cannot be traced to individual products. Example: general administration, plant rent, building security." },
  { chapter: 5, term: "Broad Averaging", definition: "Also called peanut-butter costing. Spreading the cost of resources uniformly to cost objects when individual products use those resources in nonuniform ways. Leads to product undercosting and overcosting." },
  { chapter: 5, term: "Product Undercosting", definition: "When the cost measurement system reports a cost for a product that is below the cost of the resources the product actually consumes. Undercosted products are underpriced, potentially causing losses." },
  { chapter: 5, term: "Product Overcosting", definition: "When the cost measurement system reports a cost for a product that is above the cost of the resources the product actually consumes. Overcosted products are overpriced, potentially losing market share." },
  { chapter: 5, term: "Product-Cost Cross-Subsidization", definition: "When a company undercosts one product, it overcosts at least one other product. The undercosted product is subsidized by the overcosted product." },
  { chapter: 5, term: "Refined Costing System", definition: "A costing system that replaces broad averages with better measurement of the costs of indirect resources used by different cost objects. Three guidelines: trace more costs as direct, increase indirect-cost pools, identify cost drivers." },
  { chapter: 5, term: "Activity-Based Management (ABM)", definition: "A method of management decision making that uses ABC information to improve customer satisfaction and profitability. Includes pricing decisions, product-mix decisions, cost reduction, process improvement, and product and process design." },
  { chapter: 5, term: "Time-Driven Activity-Based Costing (TDABC)", definition: "An ABC system that uses available time to allocate activity costs to cost objects. Requires two estimates: the cost of supplying resource capacity, and the time each activity consumes." },
  { chapter: 5, term: "First-Stage Allocation", definition: "The process of assigning costs from account classifications (salaries, depreciation, etc.) to activity-cost pools based on cause-and-effect relationships." },
  { chapter: 5, term: "Second-Stage Allocation", definition: "The allocation of costs from activity-cost pools to cost objects such as products or services, using cost drivers as allocation bases." },
  { chapter: 6, term: "Master Budget", definition: "Expresses management's operating and financial plans for a specified period (usually a fiscal year) and includes a set of budgeted financial statements. It is the initial plan of what the company intends to accomplish in the period." },
  { chapter: 6, term: "Operating Budget", definition: "The budgeted income statement and its supporting budget schedules. The starting point is the revenues budget. Supporting schedules include production, direct materials, direct labor, manufacturing overhead, ending inventories, cost of goods sold, and operating costs." },
  { chapter: 6, term: "Financial Budget", definition: "The part of the master budget made up of the capital expenditures budget, the cash budget, the budgeted balance sheet, and the budgeted statement of cash flows." },
  { chapter: 6, term: "Rolling Budget", definition: "Also called a continuous budget or rolling forecast. A budget that is always available for a specified future period, created by continually adding a new period as the most recent period ends." },
  { chapter: 6, term: "Activity-Based Budgeting (ABB)", definition: "A budgeting method that focuses on the budgeted cost of the activities necessary to produce and sell products and services. Uses activity-based cost drivers rather than output-based drivers." },
  { chapter: 6, term: "Responsibility Center", definition: "A part, segment, or subunit of an organization whose manager is accountable for a specified set of activities. The four types are cost centers, revenue centers, profit centers, and investment centers." },
  { chapter: 6, term: "Cost Center", definition: "A responsibility center in which the manager is accountable for costs only. Example: a manufacturing department or maintenance department." },
  { chapter: 6, term: "Revenue Center", definition: "A responsibility center in which the manager is accountable for revenues only. Example: a sales department evaluated solely on bookings." },
  { chapter: 6, term: "Profit Center", definition: "A responsibility center in which the manager is accountable for both revenues and costs. Example: a hotel general manager responsible for the hotel's operating income." },
  { chapter: 6, term: "Investment Center", definition: "A responsibility center in which the manager is accountable for investments, revenues, and costs. Example: a division manager who decides on capital expenditures and is evaluated on return on investment." },
  { chapter: 6, term: "Responsibility Accounting", definition: "A system that measures the plans, budgets, actions, and actual results of each responsibility center. Associates financial items with managers on the basis of which manager has the most knowledge about specific items." },
  { chapter: 6, term: "Controllability", definition: "The degree of influence a specific manager has over costs, revenues, or related items for which he or she is responsible. A controllable cost is any cost primarily subject to the influence of a given responsibility center manager for a given period." },
  { chapter: 6, term: "Budgetary Slack", definition: "The practice of underestimating budgeted revenues or overestimating budgeted costs to make budgeted targets easier to achieve. Occurs when managers are evaluated against the budget they helped create." },
  { chapter: 6, term: "Kaizen Budgeting", definition: "A budgeting approach that explicitly incorporates continuous improvement anticipated during the budget period into the budget numbers. Kaizen is Japanese for continuous improvement." },
  { chapter: 6, term: "Cash Budget", definition: "A schedule of expected cash receipts and cash disbursements. Predicts the effects on the cash position at the given level of operations. Shows when borrowing is needed and when loans can be repaid." },
  { chapter: 6, term: "Financial Planning Models", definition: "Mathematical representations of the relationships among operating activities, financing activities, and other factors that affect the master budget. Enable sensitivity analysis." },
  { chapter: 6, term: "Pro Forma Statements", definition: "Another name for budgeted financial statements. Represents management's expectations of financial results before the period begins." },
  { chapter: 7, term: "Variance", definition: "The difference between actual results and expected (budgeted) performance. Variances bring together the planning and control functions of management." },
  { chapter: 7, term: "Static Budget", definition: "Also called the master budget. Based on the level of output planned at the start of the budget period. Developed around a single planned output level." },
  { chapter: 7, term: "Static-Budget Variance", definition: "The difference between the actual result and the corresponding budgeted amount in the static budget. Equals the flexible-budget variance plus the sales-volume variance." },
  { chapter: 7, term: "Flexible Budget", definition: "Calculates budgeted revenues and costs based on the actual output in the budget period. Prepared retroactively after managers know the actual output level." },
  { chapter: 7, term: "Flexible-Budget Variance", definition: "The difference between an actual result and the corresponding flexible-budget amount. A better measure of performance than the static-budget variance because it compares actual and budgeted amounts for the same output level." },
  { chapter: 7, term: "Sales-Volume Variance", definition: "The difference between a flexible-budget amount and the corresponding static-budget amount. Arises solely from the difference between actual quantity sold and budgeted quantity sold." },
  { chapter: 7, term: "Selling-Price Variance", definition: "The flexible-budget variance for revenues. Arises solely from the difference between the actual selling price and the budgeted selling price." },
  { chapter: 7, term: "Management by Exception", definition: "A practice whereby managers focus more closely on areas that are not operating as expected and less closely on areas that are. Variances facilitate management by exception." },
  { chapter: 7, term: "Standard", definition: "A carefully determined price, cost, or quantity used as a benchmark for judging performance. Usually expressed on a per-unit basis." },
  { chapter: 7, term: "Standard Cost", definition: "A carefully determined cost of a unit of output. Standard cost per output unit = Standard input allowed per output unit x Standard price per input unit." },
  { chapter: 7, term: "Price Variance", definition: "Also called rate variance. The difference between actual price and budgeted price, multiplied by the actual input quantity. Measures whether inputs cost more or less than standard." },
  { chapter: 7, term: "Efficiency Variance", definition: "Also called usage variance. The difference between actual input quantity used and budgeted input quantity allowed for actual output, multiplied by budgeted price. Measures whether more or fewer inputs were used than standard." },
  { chapter: 7, term: "Benchmarking", definition: "The continuous process of comparing one company's performance levels against the best levels of performance in competing companies or in companies having similar processes." },
  { chapter: 8, term: "Variable Overhead Flexible-Budget Variance", definition: "The difference between actual variable overhead costs incurred and flexible-budget variable overhead amounts. Equals the sum of the spending variance and efficiency variance." },
  { chapter: 8, term: "Variable Overhead Spending Variance", definition: "The difference between the actual variable overhead cost per unit of the cost-allocation base and the budgeted variable overhead cost per unit, multiplied by the actual quantity of the cost-allocation base used." },
  { chapter: 8, term: "Variable Overhead Efficiency Variance", definition: "The difference between the actual quantity of the cost-allocation base used and the budgeted quantity allowed for actual output, multiplied by the budgeted variable overhead cost per unit of the base." },
  { chapter: 8, term: "Fixed Overhead Flexible-Budget Variance", definition: "The difference between actual fixed overhead costs and fixed overhead costs in the flexible budget. For fixed overhead, this equals the spending variance because there is no efficiency variance." },
  { chapter: 8, term: "Fixed Overhead Spending Variance", definition: "Same as the fixed overhead flexible-budget variance. The difference between actual fixed overhead costs and budgeted fixed overhead costs." },
  { chapter: 8, term: "Production-Volume Variance", definition: "Also called the denominator-level variance. The difference between budgeted fixed overhead and fixed overhead allocated on the basis of actual output produced. Arises only for fixed costs." },
  { chapter: 8, term: "Denominator Level", definition: "The quantity of the cost-allocation base used to calculate the budgeted fixed overhead cost rate. Typically the budgeted output level for the period." },
  { chapter: 8, term: "4-Variance Analysis", definition: "The most detailed overhead variance analysis: variable OH spending variance, variable OH efficiency variance, fixed OH spending variance, and fixed OH production-volume variance." },
  { chapter: 8, term: "Standard Costing", definition: "A costing system that traces direct costs to output using standard prices times standard quantities, and allocates overhead using standard overhead cost rates times standard quantities of the allocation base allowed for actual output." },
  { chapter: 8, term: "Total-Overhead Variance", definition: "The difference between total actual overhead incurred and total overhead allocated to actual output. Equals the sum of all four variances in the 4-variance analysis." },
  { chapter: 8, term: "Operating-Income Volume Variance", definition: "The difference between the static-budget operating income and the budgeted operating income for the actual units produced. Together with the production-volume variance, it comprises the sales-volume variance." },
  { chapter: 8, term: "Underallocated Overhead", definition: "Occurs when actual overhead costs exceed allocated overhead costs. The total of underallocated variable and fixed overhead equals the total-overhead variance when unfavorable." },
  { chapter: 9, term: "Absorption Costing", definition: "Inventory costing method in which all manufacturing costs, variable and fixed, are included as inventoriable costs. Required for external financial reporting under GAAP." },
  { chapter: 9, term: "Variable Costing", definition: "Inventory costing method in which only variable manufacturing costs are inventoriable. Fixed manufacturing costs are expensed in the period incurred. Also called direct costing." },
  { chapter: 9, term: "Throughput Costing", definition: "Extreme form of variable costing in which only direct materials costs are inventoriable. All other costs including direct labor and variable overhead are period costs. Also called super-variable costing." },
  { chapter: 9, term: "Direct Costing", definition: "Alternative name for variable costing. A misnomer because variable manufacturing overhead, an indirect cost, is inventoriable under this method." },
  { chapter: 9, term: "Theoretical Capacity", definition: "Level of capacity based on producing at full efficiency all the time. Does not allow for any downtime or interruptions. Represents an idealized upper bound." },
  { chapter: 9, term: "Practical Capacity", definition: "Theoretical capacity reduced for unavoidable interruptions such as scheduled maintenance and holidays. Represents the maximum output a plant can realistically achieve." },
  { chapter: 9, term: "Normal Capacity Utilization", definition: "Capacity level that satisfies average customer demand over 2 to 3 years incorporating seasonal, cyclical, and trend factors. A demand-based measure." },
  { chapter: 9, term: "Master-Budget Capacity Utilization", definition: "Expected level of capacity utilization for the current budget period, typically one year. Used for short-run planning and performance evaluation of marketing managers." },
  { chapter: 9, term: "Production-Volume Variance", definition: "Difference between budgeted fixed manufacturing overhead and fixed overhead allocated using the budgeted rate times actual output. Exists only under absorption costing." },
  { chapter: 9, term: "Downward Demand Spiral", definition: "Continuing reduction in demand that occurs when competitor prices are not met. As demand drops, unit costs rise under demand-based costing systems, further reducing competitiveness." },
  { chapter: 10, term: "Cost Function", definition: "A mathematical description of how a cost changes with changes in the level of an activity. General form: y = a + bX." },
  { chapter: 10, term: "Linear Cost Function", definition: "A cost function in which the graph of total costs based on the level of a single activity is a straight line within the relevant range." },
  { chapter: 10, term: "Slope Coefficient (b)", definition: "The amount by which total cost changes when a one-unit change occurs in the cost driver. Represents the variable cost per unit of activity." },
  { chapter: 10, term: "Constant / Intercept (a)", definition: "The component of total cost that does not vary with changes in the level of the activity within the relevant range. The fixed cost component." },
  { chapter: 10, term: "Mixed Cost", definition: "A cost that has both fixed and variable elements. Also called a semivariable cost. Expressed as y = a + bX." },
  { chapter: 10, term: "Cost Estimation", definition: "Measuring a cost relationship based on data from past costs and the related level of activity, used to predict future costs." },
  { chapter: 10, term: "High-Low Method", definition: "The simplest quantitative method to estimate a cost function. Uses only the highest and lowest observed values of the cost driver to estimate slope and constant." },
  { chapter: 10, term: "Regression Analysis", definition: "A statistical method that measures the average amount of change in the dependent variable associated with a unit change in one or more independent variables. Uses all observations." },
  { chapter: 10, term: "Dependent Variable (y)", definition: "The cost to be predicted and managed in a cost function estimation. Plotted on the vertical (Y) axis." },
  { chapter: 10, term: "Independent Variable (X)", definition: "The level of activity or cost driver used to predict the dependent variable. Plotted on the horizontal (X) axis." },
  { chapter: 10, term: "Goodness of Fit (R^2)", definition: "The coefficient of determination. Measures the percentage of variation in Y explained by X. Ranges from 0 to 1; 0.30 or higher generally passes the test." },
  { chapter: 10, term: "Residual Term", definition: "The vertical distance between an actual cost observation and the estimated regression line. Regression minimizes the sum of squared residuals." },
  { chapter: 10, term: "Learning Curve", definition: "A function that measures how labor-hours per unit decline as units of production increase because workers become more efficient with experience." },
  { chapter: 10, term: "Experience Curve", definition: "A broader application of the learning curve that extends to other business functions such as marketing, distribution, and customer service." },
  { chapter: 10, term: "Cumulative Average-Time Learning Model", definition: "Cumulative average time per unit declines by a constant percentage each time the cumulative quantity of units produced doubles." },
  { chapter: 10, term: "Incremental Unit-Time Learning Model", definition: "The incremental time needed to produce the last unit declines by a constant percentage each time the cumulative quantity of units produced doubles." },
  { chapter: 10, term: "Nonlinear Cost Function", definition: "A cost function for which the graph of total costs is not a straight line within the relevant range. Arises from quantity discounts, step functions, or learning effects." },
  { chapter: 10, term: "Step Cost Function", definition: "A cost function in which cost remains the same over various ranges of activity but increases by discrete amounts as activity moves from one range to the next." },
  { chapter: 10, term: "Account Analysis Method", definition: "Estimates cost functions by classifying cost accounts as variable, fixed, or mixed based on qualitative judgment about the identified level of activity." },
  { chapter: 10, term: "Conference Method", definition: "Estimates cost functions based on analysis and opinions about costs and their drivers gathered from various departments of a company." },
  { chapter: 10, term: "Industrial Engineering Method", definition: "Estimates cost functions by analyzing the relationship between inputs and outputs in physical terms. Also called the work-measurement method." },
  { chapter: 10, term: "Multicollinearity", definition: "Exists in multiple regression when two or more independent variables are highly correlated with each other, inflating standard errors of individual coefficients." },
  { chapter: 11, term: "Data Science", definition: "The use of data analytics to draw conclusions from data. Sits at the intersection of computer science, math and statistics, and substantive domain expertise." },
  { chapter: 11, term: "Predictive Modeling", definition: "A data science technique used to make predictions based on past or current data. The model learns from training data and predicts outcomes for new records." },
  { chapter: 11, term: "Decision Tree", definition: "A predictive modeling technique that segments the target variable into different regions based on a set of if-then-else rules, using recursive partitioning to reduce impurity." },
  { chapter: 11, term: "Gini Impurity", definition: "A measure of the purity of a collection of observations in a rectangle. Zero means perfectly pure (one class only). Maximum value of 0.5 for two equal classes. The algorithm minimizes Gini impurity at each cut." },
  { chapter: 11, term: "Information Gain", definition: "The reduction in Gini impurity from the level in the original rectangle to the weighted average level in the new rectangles created by a cut. The algorithm maximizes information gain." },
  { chapter: 11, term: "Overfitting", definition: "Occurs when a model adheres too closely to the specific details of a dataset, capturing noise from random chance in addition to signal. Overfitting limits a model ability to predict future outcomes." },
  { chapter: 11, term: "Pruning", definition: "A technique in which the decision tree is not grown to its full size but is only allowed to grow to a certain depth. Pruning prevents overfitting by stopping the tree before it memorizes noise." },
  { chapter: 11, term: "Cross-Validation", definition: "The process of comparing predictions of different models on a new set of data for which the actual outcomes are already known. Managers choose the model that predicts most accurately on the validation sample." },
  { chapter: 11, term: "Holdout Sample", definition: "A completely new dataset, unseen by the model, used to test final model performance. Also called a test sample. Provides the most honest estimate of real-world predictive accuracy." },
  { chapter: 11, term: "Training Sample", definition: "The portion of data used to build and fit the model. Typically 60% of the total dataset. The model learns patterns from this data." },
  { chapter: 11, term: "Maximum Likelihood", definition: "A method for evaluating model predictions. The likelihood value L = p^y * (1-p)^(1-y) ranges from 0 to 1 and is maximized when predicted probabilities are close to actual outcomes." },
  { chapter: 11, term: "Bias-Variance Tradeoff", definition: "The tradeoff between underfitting (high bias, low variance) and overfitting (low bias, high variance). Pruning increases bias but reduces variance. The optimal depth balances both." },
  { chapter: 11, term: "Hyperparameter", definition: "A parameter that cannot be learned by running the model and must be chosen before analysis. In decision trees, the maximum depth is a hyperparameter." },
  { chapter: 11, term: "Target Leakage", definition: "Data that are not available at the time of the analysis and therefore should be excluded from the model. Including future data artificially inflates model performance and leads to poor real-world predictions." },
  { chapter: 11, term: "ROC Curve", definition: "Receiver Operating Characteristic curve. Plots the true positive rate (y-axis) against the false positive rate (x-axis) at different classification thresholds. A curve closer to the upper-left corner indicates a better model." },
  { chapter: 11, term: "Confusion Matrix", definition: "A matrix showing predicted versus actual classifications at a given threshold. Contains true positives (TP), false positives (FP), false negatives (FN), and true negatives (TN)." },
  { chapter: 11, term: "True Positives (TP)", definition: "Observations correctly predicted as positive (e.g., default loans correctly predicted as defaults). The model correctly identified the event of interest." },
  { chapter: 11, term: "False Positives (FP)", definition: "Observations incorrectly predicted as positive (e.g., repay loans falsely predicted as defaults). The model raised a false alarm." },
  { chapter: 11, term: "False Negatives (FN)", definition: "Observations incorrectly predicted as negative (e.g., default loans predicted as repay). The model missed the event of interest. Often the most costly error." },
  { chapter: 11, term: "True Negatives (TN)", definition: "Observations correctly predicted as negative (e.g., repay loans correctly predicted as repays). The model correctly identified the absence of the event." },
  { chapter: 11, term: "False Positive Rate", definition: "The fraction of negatives incorrectly identified as positives at a given threshold. Calculated as FP / (FP + TN). Plotted on the x-axis of the ROC curve." },
  { chapter: 11, term: "True Positive Rate", definition: "The fraction of positives correctly identified as positives at a given threshold. Also called sensitivity or recall. Calculated as TP / (TP + FN). Plotted on the y-axis of the ROC curve." },
  { chapter: 12, term: "Relevant Costs", definition: "Expected future costs that differ among alternative courses of action. Only relevant costs should influence decisions. Historical costs are never relevant." },
  { chapter: 12, term: "Relevant Revenues", definition: "Expected future revenues that differ among alternative courses of action. Revenues that are the same under all alternatives are irrelevant." },
  { chapter: 12, term: "Sunk Costs", definition: "Past costs that have already been incurred and cannot be changed regardless of which alternative is chosen. Always irrelevant to future decisions. Also called past costs or historical costs." },
  { chapter: 12, term: "One-Time-Only Special Order", definition: "A special order with no long-run implications. When idle capacity exists and fixed costs are unaffected, the relevant cost is only the variable cost of fulfilling the order." },
  { chapter: 12, term: "Insourcing", definition: "Producing goods or providing services within an organization rather than purchasing from an outside vendor." },
  { chapter: 12, term: "Outsourcing", definition: "Purchasing goods and services from outside vendors rather than producing them internally. Also called make-or-buy decisions." },
  { chapter: 12, term: "Make-or-Buy Decisions", definition: "Decisions about whether a producer of goods or services will insource or outsource. Quality, dependability of suppliers, and costs are the most important factors." },
  { chapter: 12, term: "Opportunity Cost", definition: "The contribution to operating income that is forgone by not using a limited resource in its next-best alternative use. Not recorded in financial accounting systems but crucial to decision making." },
  { chapter: 12, term: "Incremental Cost", definition: "The additional total cost incurred for an activity. Only includes costs that change as a result of the decision." },
  { chapter: 12, term: "Differential Cost", definition: "The difference in total cost between two alternatives. Sometimes used interchangeably with incremental cost." },
  { chapter: 12, term: "Product-Mix Decisions", definition: "Decisions managers make about which products to sell and in what quantities. When a resource is constrained, maximize contribution margin per unit of the constraining resource." },
  { chapter: 12, term: "Constraining Resource", definition: "The resource that restricts or limits the production or sale of products. Also called the limiting factor or bottleneck. Managers maximize CM per unit of the constraining resource." },
  { chapter: 12, term: "Theory of Constraints (TOC)", definition: "Describes methods to maximize operating income when faced with bottleneck and non-bottleneck operations. Focuses on keeping the bottleneck busy and increasing its efficiency." },
  { chapter: 12, term: "Throughput Margin", definition: "Revenues minus the direct material costs of goods sold. Used in TOC analysis, which treats all other operating costs as fixed in the short run." },
  { chapter: 12, term: "Bottleneck", definition: "An operation where capacity is less than the demand placed on it. The bottleneck determines the output of the entire system. Improving non-bottleneck operations does not increase total output." },
  { chapter: 12, term: "Book Value", definition: "Original cost minus accumulated depreciation of an asset. Always a sunk cost and therefore irrelevant in equipment-replacement decisions." },
  { chapter: 12, term: "Decision Model", definition: "A formal method of making a choice that often involves both quantitative and qualitative analyses. Management accountants analyze and present relevant data to guide managers decisions." },
  { chapter: 12, term: "Qualitative Factors", definition: "Outcomes that are difficult to measure accurately in numerical terms. Examples include employee morale, supplier reliability, and product quality. Must be considered alongside quantitative factors." },
  { chapter: 12, term: "Quantitative Factors", definition: "Outcomes measured in numerical terms. Financial quantitative factors can be expressed in monetary terms. Non-financial quantitative factors can be measured numerically but not in dollars." },
  { chapter: 12, term: "Full Costs of the Product", definition: "The sum of all variable and fixed costs in all business functions of the value chain. Includes R&D, design, production, marketing, distribution, and customer service costs." },
  { chapter: 13, term: "Strategy", definition: "How an organization matches its capabilities with market opportunities to accomplish its objectives." },
  { chapter: 13, term: "Product Differentiation", definition: "A strategy of offering products or services customers perceive as unique and valuable, often supporting premium prices." },
  { chapter: 13, term: "Cost Leadership", definition: "A strategy of achieving lower costs than competitors while delivering acceptable quality and functionality." },
  { chapter: 13, term: "Balanced Scorecard", definition: "A framework that translates strategy into performance measures across financial, customer, internal-business-process, and learning-and-growth perspectives." },
  { chapter: 13, term: "Strategy Map", definition: "A diagram showing cause-and-effect relationships among strategic objectives across balanced scorecard perspectives." },
  { chapter: 13, term: "Growth Component", definition: "The portion of operating-income change caused by selling more or fewer units, holding prior-period prices and efficiency constant." },
  { chapter: 13, term: "Price-Recovery Component", definition: "The portion of operating-income change caused by changes in selling prices and input prices." },
  { chapter: 13, term: "Productivity Component", definition: "The portion of operating-income change caused by using fewer or more inputs to produce actual output." },
  { chapter: 13, term: "Engineered Cost", definition: "A cost with a measurable cause-and-effect relationship between output and resources used." },
  { chapter: 13, term: "Discretionary Cost", definition: "A cost arising from periodic management decisions, with no clear measurable cause-and-effect relationship to output." },
  { chapter: 13, term: "Unused Capacity", definition: "Available resource capacity not used to support current output. Managers must decide whether to retain it for future growth or downsize." },
  { chapter: 13, term: "Downsizing", definition: "Reducing capacity levels and related costs when unused capacity is not expected to be needed." },
  { chapter: 14, term: "Target Price", definition: "The estimated price for a product or service that potential customers will be willing to pay. It is market driven rather than cost driven." },
  { chapter: 14, term: "Target Cost per Unit", definition: "The estimated long-run cost per unit that enables the company to earn its target operating income at the target price." },
  { chapter: 14, term: "Target Operating Income per Unit", definition: "The operating income the company aims to earn on each unit sold. Target cost equals target price minus this amount." },
  { chapter: 14, term: "Value Engineering", definition: "A systematic evaluation of all aspects of the value chain to reduce costs while satisfying customer needs." },
  { chapter: 14, term: "Cost-Plus Pricing", definition: "A pricing approach that adds a markup to a cost base. The markup should recover costs excluded from the base and provide the desired return." },
  { chapter: 14, term: "Cost Base", definition: "The cost amount to which a markup is added. Common bases include variable manufacturing cost, total manufacturing cost, and full product cost." },
  { chapter: 14, term: "Markup Percentage", definition: "The markup amount divided by the selected cost base. The percentage depends on which costs are included in or excluded from the base." },
  { chapter: 14, term: "Life-Cycle Costing", definition: "Tracking and accumulating costs over a products entire life, from R&D and design through production, marketing, distribution, and customer support." },
  { chapter: 14, term: "Locked-in Costs", definition: "Costs that have not yet been incurred but are committed by decisions already made, especially product design decisions." },
  { chapter: 14, term: "Customer Value", definition: "The usefulness a customer gains from a product or service. Pricing decisions must consider customer value and competitor actions, not costs alone." },
  { chapter: 14, term: "Short-Run Pricing Decision", definition: "A pricing decision for a special order or limited time period where some costs are fixed and capacity may be idle." },
  { chapter: 14, term: "Long-Run Pricing Decision", definition: "A pricing decision over a horizon long enough for managers to adjust capacity and product design. Prices should recover all value-chain costs." },
  { chapter: 15, term: "Cost Allocation", definition: "The assignment of indirect costs to a cost object, such as a customer, product, department, or distribution channel." },
  { chapter: 15, term: "Cost Object", definition: "Anything for which managers want a separate measurement of cost. Customers and distribution channels can be cost objects." },
  { chapter: 15, term: "Customer Output-Unit-Level Cost", definition: "A customer cost driven by each unit sold or shipped to a customer." },
  { chapter: 15, term: "Customer Batch-Level Cost", definition: "A customer cost driven by a batch of customer activity, such as an order, delivery, or sales visit." },
  { chapter: 15, term: "Customer-Sustaining Cost", definition: "A cost incurred to support an individual customer regardless of the number of units or orders." },
  { chapter: 15, term: "Distribution-Channel Cost", definition: "A cost incurred to support a particular channel, such as retail, wholesale, online, or dealer networks." },
  { chapter: 15, term: "Corporate-Sustaining Cost", definition: "A cost that supports the organization as a whole and is not meaningfully traceable to individual customers or channels." },
  { chapter: 15, term: "Customer Profitability Analysis", definition: "Reporting and analysis that identifies revenues, product costs, and customer-level costs to determine operating income by customer." },
  { chapter: 15, term: "Whale Curve", definition: "A graph of cumulative customer profitability after ranking customers from most profitable to least profitable." },
  { chapter: 15, term: "Sales-Mix Variance", definition: "The effect on contribution margin of selling a different mix of products than budgeted, holding total actual units constant." },
  { chapter: 15, term: "Sales-Quantity Variance", definition: "The effect on contribution margin of selling more or fewer total units than budgeted, holding the budgeted mix constant." },
  { chapter: 15, term: "Market-Share Variance", definition: "The portion of sales-quantity variance caused by changes in the company share of the market." },
  { chapter: 15, term: "Market-Size Variance", definition: "The portion of sales-quantity variance caused by changes in total industry market size." },
  { chapter: 16, term: "Support Department", definition: "A department that provides services to operating departments and other support departments but does not directly produce goods or services sold to customers. Examples: IT, HR, Administration." },
  { chapter: 16, term: "Operating Department", definition: "A department that directly adds value to products or services sold to customers. Support-department costs are allocated to operating departments for product costing and pricing." },
  { chapter: 16, term: "Direct Method", definition: "Allocates each support department's costs directly to operating departments only, ignoring any services provided to other support departments." },
  { chapter: 16, term: "Step-Down Method", definition: "Allocates support-department costs sequentially. Once a support department's costs are allocated, it receives no further allocations. Partially recognizes inter-support services." },
  { chapter: 16, term: "Reciprocal Method", definition: "Fully recognizes mutual services among support departments by solving a system of simultaneous equations. Most accurate but most complex." },
  { chapter: 16, term: "Common Cost", definition: "A cost of operating a facility, activity, or resource shared by two or more users. The challenge is allocating it fairly when no single user caused the entire cost." },
  { chapter: 16, term: "Standalone Cost-Allocation Method", definition: "Allocates common costs proportionally to each party's standalone cost. Both parties share savings equally relative to their standalone costs." },
  { chapter: 16, term: "Incremental Cost-Allocation Method", definition: "Ranks users as primary and secondary. The primary user is allocated up to their standalone cost; the secondary user gets the remainder." },
  { chapter: 16, term: "Shapley Value", definition: "Allocates common costs or revenues by averaging each party's marginal contribution across all possible orderings. Satisfies fairness criteria but requires more computation." },
  { chapter: 16, term: "Bundled Product", definition: "Two or more products or services sold together for a single price. Revenue must be allocated among the bundled items for financial reporting and profitability analysis." },
  { chapter: 16, term: "Standalone Revenue-Allocation Method", definition: "Allocates bundle revenue proportionally to each product's standalone selling price." },
  { chapter: 16, term: "Incremental Revenue-Allocation Method", definition: "Ranks products as primary and secondary. The primary product is allocated up to its standalone price; the secondary product gets the remainder." },
  { chapter: 17, term: "Joint Costs", definition: "Costs of a single process that yields multiple products simultaneously. Cannot be traced to individual products before the splitoff point." },
  { chapter: 17, term: "Splitoff Point", definition: "The juncture in a joint production process where two or more products become separately identifiable." },
  { chapter: 17, term: "Joint Products", definition: "Two or more products that have relatively high sales value and are not separately identifiable as individual products until the splitoff point." },
  { chapter: 17, term: "Byproduct", definition: "A product from a joint production process that has low total sales value compared with the total sales value of the main products." },
  { chapter: 17, term: "Separable Costs", definition: "Costs incurred beyond the splitoff point that can be attributed to individual products. These are relevant to sell-or-process-further decisions." },
  { chapter: 17, term: "Sales Value at Splitoff Method", definition: "Allocates joint costs based on the relative sales value of each product at the splitoff point. Considered the most theoretically sound method." },
  { chapter: 17, term: "Net Realizable Value (NRV) Method", definition: "Allocates joint costs based on the relative NRV (final selling price minus separable costs) of each product. Used when no market price exists at splitoff." },
  { chapter: 17, term: "Constant Gross Margin % NRV Method", definition: "Allocates joint costs so that all products earn the same gross margin percentage. Treats joint cost allocation as a residual." },
  { chapter: 17, term: "Sell-or-Process-Further Decision", definition: "A decision about whether to sell a product at the splitoff point or process it further. Joint costs are always irrelevant -- only incremental revenues and separable costs matter." },
  { chapter: 17, term: "Production Method (Byproducts)", definition: "Recognizes byproduct NRV at the time of production, reducing the joint costs allocated to main products." },
  { chapter: 17, term: "Sales Method (Byproducts)", definition: "Recognizes byproduct revenue only when the byproduct is sold. More conservative and simpler than the production method." },
  { chapter: 18, term: "Process Costing", definition: "A costing system in which the cost of a product is obtained by using broad averages to assign costs to masses of similar units. Used when identical or similar units are produced in large quantities." },
  { chapter: 18, term: "Work-in-Process (WIP)", definition: "Units that have been started but not yet completed at the end of a period. WIP must be valued in terms of equivalent units." },
  { chapter: 18, term: "Equivalent Units of Production (EUP)", definition: "A derived measure of output that takes the quantity of each input in units completed and in units in ending WIP inventory and converts them into the amount of completed output that could have been made with that quantity of input." },
  { chapter: 18, term: "Weighted-Average Method", definition: "A process-costing method that assigns the average of the costs in beginning WIP and costs added during the current period to equivalent units completed and to equivalent units in ending WIP." },
  { chapter: 18, term: "FIFO Method", definition: "A process-costing method that assigns the cost of the previous accounting period's equivalent units in beginning WIP to the first units completed and assigns the cost of equivalent units worked on during the current period to ending WIP." },
  { chapter: 18, term: "Transferred-In Costs", definition: "Costs incurred in a previous department that are carried forward as the product moves to a subsequent process. Treated like a separate cost category (similar to direct materials) in the receiving department." },
  { chapter: 18, term: "Splitoff Point", definition: "The juncture in a joint production process when two or more products become separately identifiable. Relevant to joint costing in Chapter 17." },
  { chapter: 18, term: "Five-Step Procedure", definition: "The standard process costing framework: (1) Summarize physical unit flow, (2) Compute equivalent units, (3) Compute cost per equivalent unit, (4) Summarize total costs, (5) Assign costs to units completed and ending WIP." },
  { chapter: 18, term: "Cost per Equivalent Unit", definition: "Total costs in a cost category divided by equivalent units of production in that category. Used to assign costs to completed units and ending WIP." },
  { chapter: 18, term: "Normal Spoilage", definition: "Spoilage that arises under efficient operating conditions. It is an inherent result of the process and is included in the cost of good units produced." },
  { chapter: 19, term: "Spoilage", definition: "Units of production that do not meet the standards required by customers and are discarded or sold at reduced prices." },
  { chapter: 19, term: "Normal Spoilage", definition: "Spoilage that arises under efficient operating conditions. It is inherent in the production process and is treated as a product cost, absorbed into the cost of good units." },
  { chapter: 19, term: "Abnormal Spoilage", definition: "Spoilage that is not inherent in the production process and would not arise under efficient operating conditions. It is expensed immediately as a period cost." },
  { chapter: 19, term: "Inspection Point", definition: "The stage in the production process at which products are examined to determine whether they are acceptable or spoiled. Only units that reach the inspection point bear normal spoilage costs." },
  { chapter: 19, term: "Rework", definition: "Units of production that do not meet the standards required by customers but are repaired and sold as good finished units." },
  { chapter: 19, term: "Normal Rework", definition: "Rework that is expected to occur under efficient operating conditions. Costs are charged to manufacturing overhead (spread across all jobs) or to the specific job depending on the cause." },
  { chapter: 19, term: "Abnormal Rework", definition: "Rework that is not expected to occur under efficient operating conditions. Costs are expensed immediately and never charged to WIP or overhead." },
  { chapter: 19, term: "Scrap", definition: "Residual material that results from manufacturing a product and has low sales value relative to the total value of the product." },
  { chapter: 19, term: "Production Method (Scrap)", definition: "Recognizing scrap value at the time of production by crediting Work-in-Process or Manufacturing Overhead. Reduces the cost of the job or process immediately." },
  { chapter: 19, term: "Sales Method (Scrap)", definition: "Recognizing scrap value only when the scrap is sold. No entry is made when scrap is generated; cash and scrap revenue are recorded at the point of sale." },
  { chapter: 19, term: "Weighted-Average with Spoilage", definition: "Process costing that blends beginning WIP costs with current period costs and includes spoiled units in the EUP calculation at the inspection point completion percentage." },
  { chapter: 19, term: "FIFO with Spoilage", definition: "Process costing that keeps beginning WIP costs separate. Current period CPU is based only on current period costs. Spoilage EUP is calculated at the inspection point completion percentage." },
  { chapter: 20, term: "Cost of Quality (COQ)", definition: "The costs incurred to prevent defects or that arise as a result of defects. Includes prevention, appraisal, internal failure, and external failure costs." },
  { chapter: 20, term: "Prevention Costs", definition: "Costs incurred to preclude the production of products that do not conform to specifications. Examples: design engineering, process engineering, supplier evaluation, and quality training." },
  { chapter: 20, term: "Appraisal Costs", definition: "Costs incurred to detect which individual units do not conform to specifications. Examples: inspection of materials, work-in-process testing, and finished goods inspection." },
  { chapter: 20, term: "Internal Failure Costs", definition: "Costs incurred on defective products before they are shipped to customers. Examples: scrap, rework, and re-inspection of reworked products." },
  { chapter: 20, term: "External Failure Costs", definition: "Costs incurred on defective products after they are shipped to customers. Examples: warranty repairs, customer returns, and lost future sales." },
  { chapter: 20, term: "Conformance Costs", definition: "The sum of prevention costs and appraisal costs. Costs incurred to ensure products meet quality standards." },
  { chapter: 20, term: "Nonconformance Costs", definition: "The sum of internal failure costs and external failure costs. Costs incurred because products fail to meet quality standards." },
  { chapter: 20, term: "Manufacturing Cycle Time", definition: "The time from when a customer order is received until the finished product is delivered. Includes processing, inspection, waiting, and moving time." },
  { chapter: 20, term: "Manufacturing Cycle Efficiency (MCE)", definition: "The ratio of value-added (processing) time to manufacturing cycle time. MCE = Processing Time / Manufacturing Cycle Time. A perfect MCE equals 1.0." },
  { chapter: 20, term: "Value-Added Time", definition: "Time that actually transforms the product in ways the customer values. Only processing time is value-added." },
  { chapter: 20, term: "Non-Value-Added Time", definition: "Time spent on inspection, waiting, and moving that does not transform the product. Reducing NVA time improves MCE and reduces costs." },
  { chapter: 20, term: "Pareto Diagram", definition: "A bar chart that ranks causes of a problem from most to least frequent, with a cumulative percentage line. Used to identify the vital few causes responsible for most defects." },
  { chapter: 20, term: "Customer Response Time", definition: "The time between a customer placing an order and the product being delivered. A key time-based performance measure." },
  { chapter: 20, term: "On-Time Performance", definition: "The percentage of orders delivered by the promised date. A nonfinancial quality measure that is a leading indicator of customer satisfaction." },
  { chapter: 22, term: "Net Present Value (NPV)", definition: "The sum of present values of all expected cash flows in a project, including the initial investment. Accept projects with positive NPV." },
  { chapter: 22, term: "Internal Rate of Return (IRR)", definition: "The discount rate at which a projects NPV equals zero. Accept projects whose IRR exceeds the required rate of return." },
  { chapter: 22, term: "Required Rate of Return", definition: "The minimum acceptable rate of return on a project, typically the company cost of capital or a hurdle rate set by management." },
  { chapter: 22, term: "Payback Period", definition: "The time required for accumulated cash inflows to equal the initial investment. Simple to compute but ignores cash flows after recovery and time value of money." },
  { chapter: 22, term: "Discounted Payback", definition: "Payback period computed using discounted cash flows. Recognizes time value of money but still ignores cash flows beyond the payback date." },
  { chapter: 22, term: "Accrual Accounting Rate of Return (AARR)", definition: "Average annual operating income divided by average investment. Uses accounting income rather than cash flows and ignores time value of money." },
  { chapter: 22, term: "Relevant Cash Flow", definition: "A future cash flow that differs between project alternatives. Only relevant cash flows should be used in capital budgeting analysis." },
  { chapter: 22, term: "Sunk Cost", definition: "A cost already incurred that cannot be changed by any future decision. Sunk costs are never relevant in capital budgeting." },
  { chapter: 22, term: "Opportunity Cost", definition: "The value of the best forgone alternative. For example, the rental income lost when company-owned space is used for a new project." },
  { chapter: 22, term: "Working Capital Investment", definition: "Additional current assets minus additional current liabilities required to support a project. Recovered as a cash inflow at project end." },
  { chapter: 22, term: "Terminal Cash Flow", definition: "Cash flow at the end of a project including salvage value of equipment, recovery of working capital, and any tax effects on terminal sales." },
  { chapter: 22, term: "Depreciation Tax Shield", definition: "The tax savings created by depreciation deductions. Equal to annual depreciation multiplied by the tax rate." },
  { chapter: 22, term: "Sensitivity Analysis", definition: "Recalculating NPV by varying one input at a time to identify which assumptions most affect the decision." },
  { chapter: 22, term: "Real Option", definition: "Flexibility embedded in a project such as the option to expand, abandon, or delay. Traditional NPV often undervalues projects with significant real options." },
  { chapter: 23, term: "Decentralization", definition: "The delegation of decision-making authority to lower levels in an organization, giving subunit managers responsibility for decisions affecting their unit." },
  { chapter: 23, term: "Centralization", definition: "Decision-making concentrated at the top of an organization, with subunit managers having limited discretion." },
  { chapter: 23, term: "Goal Congruence", definition: "A condition in which individual managers and the organization as a whole have aligned objectives. Performance evaluation systems should foster goal congruence." },
  { chapter: 23, term: "Responsibility Center", definition: "A part of an organization for whose performance a manager is held accountable. Types include cost centers, revenue centers, profit centers, and investment centers." },
  { chapter: 23, term: "Transfer Price", definition: "The price one subunit charges another for a product or service supplied internally. Transfer pricing affects divisional profits but not total corporate profit in a single-country setting." },
  { chapter: 23, term: "Market-Based Transfer Pricing", definition: "Setting the transfer price equal to the external market price for the same or similar goods. Works best when a perfectly competitive market exists for the transferred item." },
  { chapter: 23, term: "Cost-Based Transfer Pricing", definition: "Setting the transfer price using internal cost data -- variable cost, full cost, or cost plus a markup. Simple but may not motivate the selling division to control costs." },
  { chapter: 23, term: "Negotiated Transfer Pricing", definition: "Transfer price determined by negotiation between selling and buying divisions. Preserves divisional autonomy but may be time-consuming." },
  { chapter: 23, term: "General Transfer Pricing Rule", definition: "Minimum transfer price = incremental cost per unit + opportunity cost per unit. Sets a floor below which the selling division should refuse to transfer." },
  { chapter: 23, term: "Incremental Cost", definition: "Additional cost incurred to produce and transfer one more unit. Usually equal to variable cost per unit for the selling division." },
  { chapter: 23, term: "Opportunity Cost", definition: "Contribution margin forgone by transferring internally instead of selling externally. Zero when idle capacity exists; positive when capacity is constrained." },
  { chapter: 23, term: "Arms-Length Standard", definition: "A tax requirement that transfer prices in multinational transactions reflect prices charged in comparable transactions between unrelated parties." },
  { chapter: 23, term: "Section 482", definition: "US Internal Revenue Code provision requiring arms-length transfer pricing between affiliated entities. Similar regulations exist in most countries to limit tax-driven profit shifting." },
  { chapter: 23, term: "Tax Arbitrage", definition: "Using transfer prices to shift profit from high-tax jurisdictions to low-tax jurisdictions. Legal within the arms-length range but heavily scrutinized by tax authorities." },
  { chapter: 24, term: "Return on Investment (ROI)", definition: "Operating income divided by investment. A percentage measure that allows comparison across divisions of different sizes. Weakness: may cause managers to reject positive-RI projects that dilute the division ROI." },
  { chapter: 24, term: "Residual Income (RI)", definition: "Operating income minus a capital charge (required rate of return times investment). A dollar measure that avoids the ROI rejection problem -- any project with positive RI adds value." },
  { chapter: 24, term: "Economic Value Added (EVA)", definition: "NOPAT minus a capital charge using WACC. Refines residual income by using after-tax operating profit and the actual weighted-average cost of capital." },
  { chapter: 24, term: "NOPAT", definition: "Net Operating Profit After Tax. Operating income multiplied by (1 - tax rate). Used in EVA to measure after-tax operating performance available to all capital providers." },
  { chapter: 24, term: "WACC", definition: "Weighted-Average Cost of Capital. The blended required return on all sources of capital (debt and equity), weighted by their proportions in the capital structure." },
  { chapter: 24, term: "DuPont Analysis", definition: "Decomposition of ROI into Profit Margin times Asset Turnover. Reveals whether ROI comes from high margins (differentiation strategy) or high turnover (cost leadership strategy)." },
  { chapter: 24, term: "Profit Margin", definition: "Operating income divided by revenue. Measures how much of each revenue dollar is converted to operating profit." },
  { chapter: 24, term: "Asset Turnover", definition: "Revenue divided by investment. Measures how efficiently assets generate revenue. Also called investment turnover." },
  { chapter: 24, term: "Investment Center", definition: "A responsibility center whose manager is held accountable for revenues, costs, and the level of investment in assets used by the center." },
  { chapter: 24, term: "Goal Congruence", definition: "Alignment between individual manager incentives and overall organizational objectives. Performance metrics and compensation systems should be designed to foster goal congruence." },
  { chapter: 24, term: "Capital Charge", definition: "The minimum required return on invested capital. Equal to the required rate of return multiplied by the investment base. Subtracted from operating income to compute residual income." },
  { chapter: 24, term: "Real ROI", definition: "ROI adjusted for inflation. Computed as (1 + Nominal ROI) / (1 + Inflation Rate) - 1. Used in multinational comparisons to remove the effect of inflation on reported performance." },
  { chapter: 24, term: "Current Cost", definition: "The cost to replace an asset at current prices, as opposed to historical cost. Using current cost in the investment base produces a more economically meaningful ROI." },
  { chapter: 24, term: "Historical Cost", definition: "Original acquisition cost of an asset, less accumulated depreciation. Most commonly used in practice but can distort ROI comparisons between old and new assets." },
];

export const CHAPTERS = Array.from(new Set(TERMS.map(t => t.chapter))).sort((a,b) => a-b);
